(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zx-sj-prepa-sp-j5-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zx-sj-prepa-sp-j5-idesfm\",\n \"titre\": \"Préparation D.E (J) · J5 Santé publique IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 58,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n   \"sha256\": \"cfef47fa50d1b8029734184173064280cf7273a669584d71619e0dc62d9fb1a8\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Santé publique · Prépa D.E J5 (IDE/SFM) · J2, J5 et J10 identiques\",\n     \"slug\": \"prepa-sp-j5-idesfm\",\n     \"pages\": \"\",\n     \"count\": 58,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Santé publique\",\n     \"source\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__0\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES est composé exclusivement d'agents de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le Comité de Gestion (COGES) est un organe mixte associant les représentants de la communauté (membres communautaires) et les agents de santé (le responsable de la gestion administrative et technique étant un prestataire de soins).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__1\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le décret N°93-218 du 03 février 1993 fixe les règles de gestion des formations sanitaires rurales. Le COGES comprend entre 10 et 20 membres\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, le décret n° 93-218 du 03 février 1993 régit l'organisation et le fonctionnement des comités de gestion des formations sanitaires rurales (COGES) et fixe leur composition entre 10 et 20 membres issus de la communauté et du personnel de santé.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__2\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les membres du COGES sont nommés pour un mandat de cinq ans non renouvelables\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon les textes réglementaires régissant le COGES en Côte d'Ivoire, les membres communautaires sont désignés pour un mandat de 3 ans renouvelables, et non de cinq ans non renouvelables.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__3\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les ASC et les AT font partie d'office du COGES\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les Agents de Santé Communautaires (ASC) et les Accoucheuses Traditionnelles (AT) sont des acteurs communautaires de première ligne qui siègent de droit parmi les membres du COGES afin d'assurer le lien entre le centre de santé et les villages.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__4\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La participation aux activités du COGES est rémunérée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les fonctions exercées par les membres communautaires au sein du COGES sont bénévoles et gratuites (non salariées), même si une motivation ponctuelle peut être prévue sur la réserve supplémentaire éventuelle selon les textes.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__5\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un membre du COGES doit résider dans un village desservi par le centre de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour représenter valablement les usagers et défendre les intérêts sanitaires de la population locale, tout membre communautaire du COGES doit obligatoirement résider dans l'un des villages de l'aire sanitaire desservie par l'ESPC.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__6\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES élabore le budget semestriel du centre de santé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le responsable de la gestion administrative et technique élabore, en accord avec le comité de gestion (COGES), le budget semestriel du centre de santé à partir des ressources propres après le monitorage.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Budgétisation des ressources propres d'un ESPC et COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__7\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES ne joue aucun rôle dans la gestion des ressources humaines\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le COGES participe à la gestion des ressources humaines d'appui de l'ESPC : il peut recruter et rémunérer du personnel journalier (gardien, agent d'hygiène/manœuvre, caissier) sur le budget de fonctionnement local et contribue au choix des ASC.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__8\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES veille à la disponibilité des médicaments essentiels et des vaccins.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans le cadre de l'Initiative de Bamako, l'une des attributions majeures du COGES est d'assurer le renouvellement permanent du stock de médicaments essentiels génériques (MEG) et de soutenir l'approvisionnement et le maintien de la chaîne du froid pour les vaccins.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__9\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le COGES peut promouvoir l'acceptabilité des services offerts à la population\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"En tant qu'interface entre l'équipe soignante et les habitants, le COGES sensibilise les communautés sur l'importance de fréquenter le centre de santé dans le respect des valeurs socioculturelles locales, favorisant ainsi l'acceptabilité et l'utilisation des services.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Monitorage (Analyse des goulots d'étranglement) et COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__10\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière tient le livret de caisse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le responsable de la gestion financière (trésorier du bureau du COGES) reçoit les versements effectués par le responsable administratif et technique, assure la tenue régulière du livret de caisse et du cahier de banque, et cosigne les retraits bancaires.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__11\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le président du COGES coordonne les activités du comité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le président du COGES (issu de la communauté) dirige et coordonne les activités du comité, préside les réunions et assemblées générales, représente le COGES auprès des autorités et cosigne les actes financiers avec le trésorier.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__12\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dons et legs constituent une source de revenus du COGES.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Outre les recettes issues du recouvrement des coûts (vente des médicaments essentiels, coût des actes de santé, vente des carnets) et les subventions éventuelles, les dons et legs font partie intégrante des ressources financières du COGES.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__13\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les dépenses liées à l'eau et à l'électricité peuvent être prises en charge par le COGES\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les charges courantes d'eau, d'électricité, de pétrole/gaz pour le réfrigérateur et d'entretien des locaux figurent parmi les dépenses de fonctionnement local prises en charge sur le budget du COGES.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Budgétisation des ressources propres d'un ESPC et COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__14\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est une variable quantitative ou qualitative mesurant un aspect d'une intervention\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un indicateur sanitaire est une variable quantitative ou qualitative (taux, ratio, proportion, indice) permettant de mesurer objectivement l'état de santé d'une population ou le degré d'exécution et d'atteinte des objectifs d'une intervention.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3) et Suivi-évaluation (p. 56).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__15\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les données sont déjà des informations interprétées\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les données sont des faits bruts, des chiffres ou des observations recueillis avant tout traitement ; ce n'est qu'après leur compilation, leur analyse et leur interprétation dans un contexte donné qu'elles deviennent une information sanitaire utile à la décision.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__16\",\n       \"num\": \"21\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est le résultat du traitement et de l'analyse des données\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'information sanitaire résulte de la transformation des données brutes par la compilation, le traitement, l'analyse et l'interprétation, afin de fournir une signification utile à la planification et à la prise de décision.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__17\",\n       \"num\": \"22\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La collecte des données sanitaires consiste à enregistrer les données dans les registres et rapports\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au niveau des établissements sanitaires de premier contact (ESPC), la collecte constitue la première étape du circuit de l'information sanitaire et consiste à consigner systématiquement les actes et événements dans les registres puis sur les supports de rapportage.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (section 3.1.1, L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__18\",\n       \"num\": \"23\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le rapport mensuel des ESPC doit être transmis au district sanitaire au plus tard le 5 du mois suivant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Conformément aux normes du Système d'Information Sanitaire en Côte d'Ivoire, les ESPC doivent acheminer leur rapport mensuel d'activités au Centre de Surveillance Épidémiologique (CSE) du district sanitaire au plus tard le 5 du mois suivant (et au plus tard le 10 pour les hôpitaux de référence).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (sections 2.3.1 et 3.1.1, L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__19\",\n       \"num\": \"24\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de complétude mesure la proportion de rapports reçus parmi ceux attendus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le taux de complétude évalue l'exhaustivité de la transmission des rapports en divisant le nombre total de rapports effectivement reçus par le nombre total de rapports attendus sur une période donnée (multiplié par 100), indépendamment du délai de réception.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__20\",\n       \"num\": \"25\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information correspond au retour des informations produites vers les niveaux inférieurs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La rétro-information (feed-back) est la transmission descendante des résultats d'analyse, des synthèses et des recommandations des niveaux supérieurs (central, régional, district) vers les structures périphériques productrices des données afin d'améliorer la qualité des prestations.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__21\",\n       \"num\": \"26\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est un événement dont les effets dépassent les capacités de réaction de la communauté\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon l'OMS, une catastrophe est un événement soudain ou progressif qui provoque des perturbations graves du fonctionnement d'une société et entraîne des pertes humaines, matérielles ou environnementales dépassant les capacités propres de réaction de la communauté touchée.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des catastrophes (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__22\",\n       \"num\": \"27\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le risque est indépendant du danger et de la vulnérabilité\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"En gestion des catastrophes, le risque est directement fonction de la rencontre entre un aléa (danger) et la vulnérabilité d'une population ou d'une infrastructure exposée (Risque = Danger × Vulnérabilité).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des catastrophes (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__23\",\n       \"num\": \"28\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les tremblements de terre sont des catastrophes naturelles\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les catastrophes se classent en catastrophes naturelles (séismes ou tremblements de terre, inondations, cyclones, sécheresses) et en catastrophes d'origine humaine ou technologique (accidents industriels, guerres, incendies).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des catastrophes (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__24\",\n       \"num\": \"29\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des rôles de l'infirmier en cas de catastrophe est de donner l'alerte\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lors de la survenue d'une catastrophe, l'infirmier ou la sage-femme en poste à l'ESPC a pour premiers réflexes de donner immédiatement l'alerte aux autorités sanitaires et administratives compétentes, d'évaluer rapidement la situation et d'organiser les premiers secours et le triage des victimes.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des catastrophes (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__25\",\n       \"num\": \"30\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision vise l'amélioration des compétences et du rendement du personnel\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La supervision est un processus formatif d'encadrement continu qui vise à renforcer les compétences techniques et organisationnelles des agents de santé, à résoudre les problèmes rencontrés sur le terrain et à améliorer la qualité et le rendement des prestations.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__26\",\n       \"num\": \"31\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La supervision est généralement une activité annoncée et périodique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Contrairement à l'inspection (qui est souvent inopinée et punitive), la supervision formative est planifiée selon un calendrier périodique et annoncée à l'avance aux agents supervisés afin de préparer les outils et favoriser un climat de confiance.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48. II. QUESTIONS À CHOIX UNIQUE / MULTIPLE\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__27\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le but principal du COGES est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sanctionner le personnel\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Associer la communauté à la gestion du centre de santé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Construire des hôpitaux universitaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Remplacer l'État\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Associer la communauté à la gestion du centre de santé\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Créé dans le cadre de la mise en œuvre de l'Initiative de Bamako, le COGES a pour finalité d'impliquer activement la communauté dans la gestion administrative, financière et matérielle de son établissement sanitaire de premier contact afin d'en assurer la pérennité et l'accessibilité.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__28\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La durée du mandat des membres du COGES est de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"1 an\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2 ans\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 ans renouvelables\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"5 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 3 ans renouvelables\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Conformément aux dispositions réglementaires régissant les comités de gestion en Côte d'Ivoire, la durée du mandat des membres du COGES est fixée à 3 ans renouvelables.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__29\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le bureau du COGES comprend\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Président, secrétaire, trésorier, un commissaire au compte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Président, responsable financier, responsable administratif et technique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Président, maire, préfet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Président et deux infirmiers\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Président, responsable financier, responsable administratif et technique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bureau exécutif du COGES est structuré autour de trois postes clés : le Président (représentant communautaire), le Responsable de la gestion financière (trésorier communautaire) et le Responsable de la gestion administrative et technique (l'infirmier ou la sage-femme chef de poste).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__30\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le responsable de la gestion financière est chargé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des consultations médicales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De l'enregistrement des recettes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De la vaccination\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De la surveillance épidémiologique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. De l'enregistrement des recettes\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le responsable de la gestion financière reçoit les fonds collectés par le responsable administratif et technique, tient le livret de caisse et le cahier de banque, enregistre les recettes et dépenses et cosigne les opérations bancaires (les actes médicaux et la vaccination relevant du personnel soignant).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Organisation et fonctionnement du COGES (L3, p. 22).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__31\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un indicateur est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une donnée brute\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une opinion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une variable permettant de mesurer un aspect d'une intervention\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Un rapport annuel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une variable permettant de mesurer un aspect d'une intervention\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un indicateur est une variable mesurable (quantitative ou qualitative) construite à partir des données traitées pour apprécier une situation sanitaire ou évaluer un aspect précis (intrants, processus, extrants, résultats) d'une intervention.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3) et Suivi-évaluation (p. 56).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__32\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'information sanitaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une donnée non traitée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une donnée contextualisée et utile\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un registre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une fiche de consultation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une donnée contextualisée et utile\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Contrairement à la donnée brute inscrite dans un registre ou une fiche, l'information sanitaire est une donnée validée, analysée, interprétée et replacée dans son contexte épidémiologique ou organisationnel afin d'orienter l'action et la décision.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__33\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La première étape du processus de génération de l'information sanitaire est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'analyse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'interprétation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La collecte\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La diffusion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La collecte\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le circuit de production de l'information sanitaire suit un enchaînement chronologique débutant par la collecte des données à la source (registres, fiches), suivie de la compilation/transmission, du traitement/analyse, de l'interprétation et enfin de la diffusion/rétro-information.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__34\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le taux de promptitude est calculé à partir\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Des consultations\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Des rapports reçus dans le délai requis\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Des supervisions\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Des naissances\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Des rapports reçus dans le délai requis\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le taux de promptitude mesure la ponctualité de la transmission des rapports : il se calcule en divisant le nombre de rapports reçus au plus tard à la date limite réglementaire (le 5 du mois suivant pour un ESPC) par le nombre total de rapports attendus, multiplié par 100.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (section 2.3.1, L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__35\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La rétro-information est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une transmission ascendante\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une sanction administrative\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un retour des informations vers les producteurs des données\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une analyse statistique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un retour des informations vers les producteurs des données\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La rétro-information constitue la boucle descendante du système d'information sanitaire par laquelle les niveaux supérieurs (district, région, niveau central) renvoient les analyses, comparaisons et recommandations aux formations sanitaires qui ont produit les données.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__36\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Selon l'OMS, le SIS sert à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Construire des centres de santé\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fournir des renseignements sanitaires pour la prise de décision\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Recruter du personnel\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Payer les agents\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Fournir des renseignements sanitaires pour la prise de décision\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon l'OMS, la finalité du Système d'Information Sanitaire (SIS) est de produire, analyser et diffuser des renseignements fiables et opportuns sur l'état de santé des populations et le fonctionnement des services afin d'éclairer la prise de décision à tous les niveaux de la pyramide sanitaire.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__37\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le niveau central de gestion des données sanitaires est représenté par\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'EPHR\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le District sanitaire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La DIIS\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'ESPC\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La DIIS\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Au sommet de la pyramide du système d'information sanitaire en Côte d'Ivoire, la coordination nationale, la centralisation et le traitement des données sanitaires sont assurés par la Direction de l'Informatique et de l'Information Sanitaire (DIIS).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion de l'information sanitaire (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__38\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une catastrophe est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une urgence mineure\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un événement sans impact\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un événement dépassant la capacité de réaction de la communauté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une simple vulnérabilité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Un événement dépassant la capacité de réaction de la communauté\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Une catastrophe se distingue d'un simple accident ou d'une urgence courante par l'ampleur de ses conséquences humaines et matérielles qui submergent les capacités locales de réponse et nécessitent le déclenchement d'un plan d'urgence et une aide extérieure.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Gestion des catastrophes (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__39\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style de supervision adapté aux situations d'urgence est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Démocratique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Participatif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Autocratique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Laisser-faire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Autocratique\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En situation d'urgence (catastrophe, épidémie aiguë, geste mettant en jeu le pronostic vital), le superviseur doit adopter un style autocratique (directif) permettant de prendre des décisions rapides, fermes et immédiatement exécutées sans perte de temps.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__40\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La méthode directe de supervision repose sur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'analyse documentaire uniquement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'observation directe du personnel au travail\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le questionnaire administratif\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le rapport annuel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. L'observation directe du personnel au travail\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La méthode directe consiste pour le superviseur à observer directement l'agent de santé pendant qu'il exécute une tâche (consultation, vaccination, soins) à l'aide d'une grille d'observation, sans l'interrompre sauf si un geste met en danger la vie du patient.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision (section 6.1.1), p. 48.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__41\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les outils du superviseur figure\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La fiche d'observation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le carnet de vaccination\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le registre de consultation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La carte sanitaire nationale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La fiche d'observation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour mener objectivement sa visite, le superviseur utilise des outils spécifiques tels que la fiche (ou grille) d'observation, la liste de contrôle (check-list), le guide d'entretien et le cahier de supervision (les registres et carnets étant les outils quotidiens du prestataire).\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__42\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le style démocratique de supervision\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Empêche toute initiative\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Repose sur la participation des collaborateurs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Est réservé aux urgences\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Exclut le dialogue\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Repose sur la participation des collaborateurs\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le style démocratique (ou participatif) favorise le dialogue, l'écoute mutuelle, l'association des collaborateurs à la recherche de solutions et l'encouragement de leurs initiatives personnelles dans l'exécution des activités.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Supervision, p. 48 ; Document révisé L2 2023-2024 validé, p. 48. III. CAS CLINIQUE 1 — MONITORAGE ET GESTION FINANCIÈRE DU CSR DE GNIMPLEU Énoncé du cas clinique 1 : L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultation curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__43\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'accessibilité géographique (AG) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"60 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"100 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 80 %.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'accessibilité géographique rapporte la population résidant dans la zone d'accessibilité (6 400 habitants dans le rayon de 10 km) à la population totale de l'aire sanitaire (8 000 habitants) : AG = 6 400 × 100 = 80 %. 8 000\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Monitorage (section 4.3) ; Formules de Santé Publique — Document harmonisé, chap. 6.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__44\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La population cible semestrielle est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4 000 personnes.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6400 personnes.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"2400 personnes.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1800 personnes.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 4 000 personnes.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour le monitorage des consultations curatives (CSC) portant sur toute la population, la population cible annuelle est de 8 000 habitants ; sur un semestre (6 mois), la population cible semestrielle correspond à la moitié de la cible annuelle, soit 8 000 2 = 4 000 personnes.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 6 (Monitorage des services de santé).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__45\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"L'utilisation des services (US) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"70 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"100 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"60 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"80 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 60 %.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'utilisation des services (US) mesure la proportion de la population cible semestrielle (4 000 personnes) ayant eu au moins un contact curatif avec le centre (2 400 personnes) : US = 24 400 000 × 100 = 60 %.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Monitorage ; Formules de Santé Publique — Document harmonisé, chap. 6.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__46\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture adéquate (CA) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"45 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"85 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"65 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 45 %.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La couverture adéquate (CA) rapporte le nombre de personnes ayant reçu le traitement complet au tarif réglementaire (1 800 personnes) à la population cible semestrielle (4 000 personnes) : CA = 14 800 000 × 100 = 45 %.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Monitorage (section 4.5) ; Formules de Santé Publique — Document harmonisé, chap. 6.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__47\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"La couverture effective (CE) est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"37%\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"3,7%\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"5,3 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"73%\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 37%\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La couverture effective (CE) rapporte le nombre de personnes ayant reçu des soins complets et conformes aux normes de qualité (1 500 personnes) à la population cible semestrielle (4 000 personnes) : 14 500 000 × 100 = 37,5 %, arrondi par défaut à 37 %.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 6 (Monitorage des services de santé).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__48\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspondent aux FR ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"100 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"4000 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 400 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 400 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le Fonds de Réserve (FR) correspond à la part du solde bancaire (1 000 000 F CFA) disponible en dehors des recettes du semestre monitoré déjà versées sur le compte (600 000 F CFA) : FR = 1 000 000 − 600 000 = 400 000 F CFA.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 7 (Gestion financière du centre de santé).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__49\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond à la SAB\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"600 000 F CFA\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 000 F CFA\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8 000 000 F CFA\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 600 000 F CFA\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon les données du cas clinique, la Somme à Budgétiser (SAB) correspondant aux recettes du semestre monitoré disponibles pour la budgétisation s'élève directement à 600 000 F CFA.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 7 (Gestion financière du centre de santé).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__50\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Quel montant correspond aux dépenses de fonctionnement local ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"100 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"600 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"300 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 300 000 F CFA.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"D'après la formule du cours, les dépenses de fonctionnement local (DFL) sont égales à la différence entre la somme totale disponible (1 000 000 F CFA) et les dépenses obligatoires retenues (700 000 F CFA), soit 1 000 000 − 700 000 = 300 000 F CFA.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Budgétisation des ressources propres d'un ESPC ; Formules de Santé Publique — Document harmonisé, chap. 7.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__51\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond de réparation de l'immeuble\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"40 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"60 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 30 000 F CFA.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon la clé de répartition budgétaire du cours sur le COGES, le plafond autorisé pour les petites réparations et l'entretien de l'immeuble sur l'enveloppe de fonctionnement local (300 000 F CFA, soit 10 %) est fixé à 30 000 F CFA.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Budgétisation des ressources propres d'un ESPC (L3).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__52\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 1 — L'équipe du Centre de Santé Rural de Gnimpleu réalise le monitorage des consultations curatives (CSC) sur un semestre. La population totale annuelle est de 8 000 habitants, dont 6 400 résidents dans le rayon de 10 km. Au cours du semestre, 2 400 personnes distinctes ont eu au moins un contact curatif avec l'ESPC ; parmi ces consultants, 1 800 ont reçu un traitement et payé le prix correct ; parmi ces 1 800, 1 500 ont en outre été traités selon les directives nationales avec des médicaments bien conservés et non périmés. Un dossier individuel révèle un traitement facturé correctement mais délivré avec un médicament périmé. À la veille du monitorage, le solde bancaire est de 1 000 000 F CFA, dont 600 000 F CFA correspondent à des recettes du semestre monitoré déjà déposées ; le solde intègre les intérêts et agios pertinents. Les RVME justifiées par reçus sont de 400 000 F CFA et les RCAS de 600 000 F CFA. Les DO retenues dans le plan d'affectation sont de 700 000 F CFA. Les montants bancaires et les recettes sont fournis selon les conventions du support, sans supposer que la SAB et le FR représentent une même masse financière.\",\n       \"text\": \"Le plafond des imprévus\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"15 000 F CFA.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"150 000 F CFA.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 000 F CFA.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"10 000 F CFA.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 15 000 F CFA.\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Conformément aux règles de budgétisation des ressources propres d'un ESPC, la ligne budgétaire consacrée aux dépenses imprévues est plafonnée à 5 % de l'enveloppe de fonctionnement local (5 % × 300 000 F CFA), soit 15 000 F CFA.\\n\\nSource : Cours Santé Publique L1, L2, L3 révisé 2025-2026, chap. Budgétisation des ressources propres d'un ESPC (L3). IV. CAS CLINIQUE 2 — GESTION DES VACCINS AU CSR DE ZRANWOPLEU Énoncé du cas clinique 2 : Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__53\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux d'utilisation du mois écoulé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"80 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 90 %.\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le taux d'utilisation (TU) rapporte le nombre de doses administrées (180) au nombre total de doses sorties du stock (200) : TU = 180 200 × 100 = 90 %.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__54\",\n       \"num\": \"59\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le taux de perte correspondant ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5 %.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"10 %.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 %.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"90 %.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 10 %.\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"TP = (doses sorties − doses administrées) / doses sorties × 100 = (200 − 180) / 200 × 100 = 10 %. On peut aussi faire TP = 100 − TU = 100 − 90 = 10 %.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__55\",\n       \"num\": \"60\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel facteur de perte découle de ce taux ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0,90.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1,00.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Environ 1,11.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"2,00.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Environ 1,11.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"FP = 100 / (100 − TP) = 100 / 90 = 1,11. C'est aussi le facteur de perte du DTC-HepB-Hib (Penta) dans le tableau du cours.\\n\\nSource : Document révisé L2 2023-2024, « Gestion des vaccins et consommables » ; Formules Santé publique harmonisées, chap. 5\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__56\",\n       \"num\": \"61\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quel est le besoin réel pour le mois suivant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"280 doses.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"400 doses.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"500 doses.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"520 doses.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 500 doses.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le stock de sécurité (SS) étant égal à 25 % du besoin théorique (0,25 × 400 = 100 doses), le besoin réel (BR) correspond à la somme du besoin théorique et du stock de sécurité : BR = 400 + 100 = 500 doses.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-sp-j5-idesfm__57\",\n       \"num\": \"62\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE 2 — Dans le Centre de Santé de Zranwopleu, Monsieur KONAN, l'infirmier Chef de poste a fait sortir 200 doses de Penta durant le mois et 180 doses ont été administrées. Pour le mois suivant, le besoin théorique (BT) est de 400 doses ; le stock de sécurité pour les vaccins est de 25 % du BT et le stock utilisable déjà disponible est de 120 doses. Toutes les quantités sont exprimées en doses.\",\n       \"text\": \"Quelle quantité de doses faut-il commander, sous réserve du conditionnement en flacons ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"120.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"280.\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"380.\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"500.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 380.\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La quantité à commander (QC) s'obtient en retranchant le stock utilisable déjà disponible (120 doses) du besoin réel (500 doses) : QC = 500 − 120 = 380 doses.\\n\\nSource : Formules de Santé Publique — Document harmonisé, chap. 5 (Gestion des vaccins et consommables).\",\n       \"sourceDoc\": \"Prépa D.E — J5 Santé publique IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_SANTE_PUBLIQUE_IDE-SFM_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
